function renderLocais(){
  const grid=$('locais-grid'); if(!grid) return;
  grid.innerHTML='';
  LIBS.locais.filter(loc => loc.id !== -1).forEach(loc=>{
    const card=document.createElement('div');
    card.className='card';
    card.style.margin=0;
    card.innerHTML=`
      <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:10px">
        <div>
          <div style="font-size:14px;font-weight:700;color:var(--text)">${escHTML(loc.nome)}</div>
          <div style="font-size:12px;color:var(--text3);margin-top:2px">${escHTML(loc.tipo)}</div>
        </div>
        <div style="display:flex;gap:6px;align-items:center">
          ${loc.id===-1?'<span style="font-size:12px;color:var(--text3);background:var(--bg2);padding:2px 7px;border-radius:99px;font-weight:600">INTERNO</span>':''}
          <button class="btn btn-ghost btn-sm" onclick="editarLocal(${loc.id})"><i class=ph-pencil-simple></i></button>
          ${loc.id===-1?'':'<button class="btn btn-ghost btn-sm" style="color:var(--red)" onclick="deletarItem(\'locais\','+loc.id+')"><i class=ph-x></i></button>'}
        </div>
      </div>
      <div style="font-size:12px;font-weight:600;color:var(--text3);margin-bottom:6px">Equipamentos (${loc.equipamentos.length})</div>
      <div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:10px">
        ${loc.equipamentos.map(e=>`<span class="badge badge-gray" style="font-size:12px">${escHTML(EQUIP_NOME[e]||e)}</span>`).join('')}
      </div>
      ${loc.obs?`<div style="font-size:12px;color:var(--text2)">${escHTML(loc.obs)}</div>`:''}
    `;
    grid.appendChild(card);
  });
  const userLocais = LIBS.locais.filter(l => l.id !== -1);
  if(!userLocais.length) grid.innerHTML='<div class="empty"><i class=ph-map-pin></i><div class="empty-title">Nenhum local cadastrado</div><div class="empty-text">Cadastre onde seus alunos treinam. A prescrição só usa os equipamentos disponíveis no local.</div></div>';
}

function abrirModalLocal(){ preencherModalLocal(null); $('modal-local').classList.remove('hidden'); }
function fecharModalLocal(){ $('modal-local').classList.add('hidden'); }

function preencherModalLocal(loc){
  $('local-edit-id').value = loc?loc.id:'';
  $('modal-local-title').textContent = loc?'Editar Local':'Novo Local de Treino';
  $('local-nome').value = loc?.nome||'';
  $('local-tipo').value = loc?.tipo||'Academia completa';
  $('local-obs').value  = loc?.obs||'';
  // Checkboxes de equipamentos
  const wrap=$('local-equip-wrap'); wrap.innerHTML='';
  EQUIP_LISTA.forEach(({chave, nome})=>{
    const checked = loc?.equipamentos?.includes(chave) ?? false;
    const label=document.createElement('label');
    label.style.cssText='display:flex;align-items:center;gap:6px;font-size:12px;color:var(--text2);cursor:pointer';
    label.innerHTML=`<input type="checkbox" style="width:auto;flex-shrink:0" value="${chave}" ${checked?'checked':''}> ${nome}`;
    wrap.appendChild(label);
  });
}

function editarLocal(id){
  const loc=LIBS.locais.find(l=>l.id===id); if(!loc) return;
  preencherModalLocal(loc);
  $('modal-local').classList.remove('hidden');
}

function coletarLocalDoForm(){
  const id_val = $('local-edit-id').value;
  const equips = [...$('local-equip-wrap').querySelectorAll('input[type=checkbox]:checked')].map(cb=>cb.value);
  return {
    id: id_val ? parseInt(id_val) : novoId(),
    nome:$('local-nome').value.trim()||'Sem nome',
    tipo:$('local-tipo').value,
    equipamentos:equips,
    obs:$('local-obs').value.trim(),
  };
}
function gravarLocal(novo){
  const idx=LIBS.locais.findIndex(l=>l.id===novo.id);
  if(idx>=0) LIBS.locais[idx]=novo; else LIBS.locais.push(novo);
  saveLibs(LIBS);
}
function salvarLocal(){
  gravarLocal(coletarLocalDoForm());
  fecharModalLocal(); renderLocais();
  // Forca sync imediato pro Supabase (nao depende do debounce de 1.5s)
  if(typeof supaSalvarAgora === 'function') supaSalvarAgora();
}
// Autosave — grava a cada edicao no modal, mesmo sem clicar em "Salvar"; fixa o
// id no campo oculto na primeira gravacao pra nao duplicar nas proximas.
attachAutosave('modal-local', coletarLocalDoForm, (novo) => { $('local-edit-id').value = novo.id; gravarLocal(novo); });

