// BIBLIOTECA DE TREINOS
// ══════════════════════════════════════════════════════════════════════════

function renderBiblioteca(){
  const grid=$('bib-grid'); if(!grid) return;
  grid.innerHTML='';

  const fObj  = ($('bib-filtro-obj') ||{}).value||'';
  const fNv   = ($('bib-filtro-nv')  ||{}).value||'';
  const fFreq = ($('bib-filtro-freq')||{}).value||'';
  const fSexo = ($('bib-filtro-sexo')||{}).value||'';

  // Show/hide active-student filter button
  const s = getActive();
  const btnFiltrar = $('bib-btn-filtrar-aluno');
  if(btnFiltrar) btnFiltrar.style.display = s ? 'inline-flex' : 'none';

  let lista = LIBS.biblioteca.filter(b=>{
    if(fObj  && b.objetivo !== fObj)   return false;
    if(fNv   && b.nivel    !== fNv)    return false;
    if(fFreq && b.freq     !== fFreq)  return false;
    if(fSexo && b.sexo && b.sexo !== '' && b.sexo !== fSexo) return false;
    return true;
  });

  if(!lista.length){
    grid.innerHTML=`<div class="empty" style="grid-column:1/-1"><i class=ph-books></i><div class="empty-title">Nenhum template encontrado</div>${LIBS.biblioteca.length===0 ? '<div class="empty-text">Aprove uma prescrição e use Salvar na Biblioteca para começar.</div>' : ''}</div>`;
    return;
  }

  lista.forEach(b=>{
    const card=document.createElement('div');
    card.className='card'; card.style.margin=0;

    // Origem badge
    const origemHtml = b.origem_aluno
      ? `<div style="font-size:12px;color:var(--text3);margin-top:2px"><i class=ph-push-pin></i> Origem: <strong>${escHTML(b.origem_aluno)}</strong>${b.origem_data?' · '+b.origem_data:''}</div>`
      : '';

    // Compatibility match with active student
    let matchBadge = '';
    const ultimoTreino = s ? getUltimoTreino(s) : {};
    if(s && ultimoTreino.objetivo){
      const pObj   = ultimoTreino.objetivo;
      const pNivel = s.anamnese?.nivel||'';
      const pFreq  = ultimoTreino.frequencia||'';
      const pSexo  = s.perfil?.sexo||'';
      const matchObj  = !b.objetivo || b.objetivo===pObj;
      const matchNv   = !b.nivel    || b.nivel===pNivel;
      const matchFreq = !b.freq     || b.freq===pFreq;
      const matchSx   = !b.sexo     || b.sexo===''   || b.sexo===pSexo;
      const score = [matchObj,matchNv,matchFreq,matchSx].filter(Boolean).length;
      if(score===4) matchBadge='<span class="badge badge-green" style="font-size:12px"><i class=ph-check></i> Perfil compativel</span>';
      else if(score>=2) matchBadge=`<span class="badge badge-amber" style="font-size:12px">≈ ${score}/4 criterios</span>`;
    }

    // Sessoes summary
    const sessoes = b.sessoes||[];
    const sessoesHtml = sessoes.length
      ? `<div style="margin-top:10px">
          <div style="font-size:12px;font-weight:600;color:var(--text3);margin-bottom:5px">${sessoes.length} sessao(oes)</div>
          ${sessoes.map(ses=>`
            <div style="margin-bottom:4px">
              <span style="font-size:12px;font-weight:600;color:var(--text)">${escHTML(ses.label)}</span>
              <span style="font-size:12px;color:var(--text3);margin-left:6px">${(ses.exercicios||[]).length} exercicio(s)</span>
            </div>
            ${(ses.exercicios||[]).slice(0,3).map(e=>
              `<div style="font-size:12px;color:var(--text2);padding-left:12px">• ${escHTML(e.nome)} ${e.series?e.series+'×':''} ${escHTML(e.reps||'')}</div>`
            ).join('')}
            ${(ses.exercicios||[]).length>3?`<div style="font-size:12px;color:var(--text3);padding-left:12px">+${(ses.exercicios||[]).length-3} mais...</div>`:''}`
          ).join('')}
        </div>`
      : b.estrutura ? `<div style="font-size:12px;background:var(--bg4);border-radius:var(--radius);padding:7px 10px;margin-top:8px;border:1px solid var(--border)">${escHTML(b.estrutura)}</div>` : '';

    const objLabel = {Hip:'Hipertrofia',Forca:'Forca',Emagr:'Emagrecimento',Comp:'Composicao',
      Resist:'Resistencia',CardioR:'Cardio',Func:'Funcional',Saude:'Saude',
      Esport:'Esportivo',Reab:'Reabilitacao',Envelhec:'Envelhecimento',Gestacao:'Gestacao'}[b.objetivo]||b.objetivo||'—';

    card.innerHTML=`
      <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:8px;gap:8px">
        <div style="flex:1;min-width:0">
          <div style="font-size:14px;font-weight:700;color:var(--text);margin-bottom:4px">${escHTML(b.nome)}</div>
          <div style="display:flex;gap:4px;flex-wrap:wrap;align-items:center">
            <span class="badge badge-green">${objLabel}</span>
            <span class="badge badge-gray">${escHTML(b.nivel||'—')}</span>
            <span class="badge badge-blue">${escHTML(b.freq||'—')}</span>
            ${b.sexo?`<span class="badge badge-amber" style="font-size:12px">${b.sexo==='M'?'<i class=ph-gender-male></i> M':'<i class=ph-gender-female></i> F'}</span>`:''}
            ${b.modelo?`<span class="badge badge-gray" style="font-size:12px">${escHTML(b.modelo)}</span>`:''}
            ${matchBadge}
          </div>
          ${origemHtml}
        </div>
        <div style="display:flex;gap:5px;flex-shrink:0">
          <button class="btn btn-ghost btn-sm" onclick="usarTemplateBib(${b.id})" title="Usar para aluno ativo"><i class=ph-play></i></button>
          <button class="btn btn-ghost btn-sm" onclick="verFichaBib(${b.id})" title="Ver ficha completa"><i class=ph-eye></i></button>
          <button class="btn btn-ghost btn-sm" onclick="editarBib(${b.id})"><i class=ph-pencil-simple></i></button>
          <button class="btn btn-ghost btn-sm" style="color:var(--red)" onclick="deletarItem('biblioteca',${b.id})"><i class=ph-x></i></button>
        </div>
      </div>
      ${b.uso?`<div style="font-size:12px;margin-bottom:6px"><span style="color:var(--accent);font-weight:600"><i class=ph-check-circle></i> </span><span style="color:var(--text2)">${escHTML(b.uso)}</span></div>`:''}
      ${b.contra?`<div style="font-size:12px;margin-bottom:6px"><span style="color:var(--red);font-weight:600"><i class=ph-x-circle></i> </span><span style="color:var(--text2)">${escHTML(b.contra)}</span></div>`:''}
      ${sessoesHtml}
      ${b.obs?`<div style="font-size:12px;color:var(--text3);margin-top:6px;font-style:italic">${escHTML(b.obs)}</div>`:''}
      ${b.ref?`<div style="font-size:12px;color:var(--text3);margin-top:4px"><i class=ph-book-open></i> ${escHTML(b.ref)}</div>`:''}
    `;
    grid.appendChild(card);
  });
}

function filtrarBibPorAlunoAtivo(){
  const s=getActive(); if(!s) return;
  const p=getUltimoTreino(s);
  const a=s.anamnese||{};
  const pf=s.perfil||{};
  const sv=(id,val)=>{ const el=$(id); if(el) el.value=val||''; };
  sv('bib-filtro-obj',  p.objetivo||'');
  sv('bib-filtro-nv',   a.nivel||'');
  sv('bib-filtro-freq', p.frequencia||'');
  sv('bib-filtro-sexo', pf.sexo||'');
  // Badge
  const badge=$('bib-aluno-badge');
  if(badge){
    badge.style.display='flex';
    badge.innerHTML=`<div style="display:flex;align-items:center;gap:8px;padding:6px 10px;background:var(--accent-dim);border-radius:var(--radius);border:1px solid var(--accent);font-size:12px">
      <span style="color:var(--accent)"><i class=ph-target></i> Filtrando por perfil:</span>
      <strong>${escHTML(pf.nome||'Aluno')}</strong>
      <span class="badge badge-green" style="font-size:12px">${escHTML(p.objetivo||'—')}</span>
      <span class="badge badge-gray" style="font-size:12px">${escHTML(a.nivel||'—')}</span>
      <span class="badge badge-blue" style="font-size:12px">${escHTML(p.frequencia||'—')}</span>
      <button class="btn btn-ghost btn-sm" onclick="limparFiltrosBib()" ><i class=ph-x></i></button>
    </div>`;
  }
  renderBiblioteca();
}

function limparFiltrosBib(){
  ['bib-filtro-obj','bib-filtro-nv','bib-filtro-freq','bib-filtro-sexo'].forEach(id=>{
    const el=$(id); if(el) el.value='';
  });
  const badge=$('bib-aluno-badge'); if(badge) badge.style.display='none';
  renderBiblioteca();
}

// ── VER FICHA COMPLETA ─────────────────────────────────────────────────────
function verFichaBib(id){
  const b=LIBS.biblioteca.find(x=>x.id===id); if(!b) return;
  const txt = b.ficha_texto || b.estrutura || 'Ficha nao disponivel.';
  const modal=document.createElement('div');
  modal.className='modal-overlay';
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:3000;display:flex;align-items:center;justify-content:center';
  modal.innerHTML=`<div class="modal" style="width:700px;max-height:90vh;overflow-y:auto">
    <div class="modal-title"><i class=ph-file-text></i> ${escHTML(b.nome)}</div>
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px">
      <span class="badge badge-green">${escHTML(b.objetivo||'—')}</span>
      <span class="badge badge-gray">${escHTML(b.nivel||'—')}</span>
      <span class="badge badge-blue">${escHTML(b.freq||'—')}</span>
      ${b.sexo?`<span class="badge badge-amber">${escHTML(b.sexo)}</span>`:''}
      ${b.modelo?`<span class="badge badge-gray">${escHTML(b.modelo)}</span>`:''}
    </div>
    ${b.origem_aluno?`<div style="font-size:12px;color:var(--text3);margin-bottom:12px"><i class=ph-push-pin></i> Origem: ${escHTML(b.origem_aluno)}${b.origem_data?' · '+b.origem_data:''}</div>`:''}
    <pre style="white-space:pre-wrap;font-variant-numeric:tabular-nums;font-size:12px;line-height:1.7;background:var(--bg4);padding:14px;border-radius:var(--radius);border:1px solid var(--border);max-height:500px;overflow-y:auto;color:var(--text)">${txt}</pre>
    <div class="btn-row">
      <button class="btn btn-ghost" onclick="this.closest('.modal-overlay').remove()">Fechar</button>
      <button class="btn btn-primary" onclick="usarTemplateBib(${id});this.closest('.modal-overlay').remove()"><i class=ph-play></i> Usar para aluno ativo</button>
    </div>
  </div>`;
  modal.addEventListener('click', e=>{ if(e.target===modal) modal.remove(); });
  document.body.appendChild(modal);
}

// ── USAR TEMPLATE ──────────────────────────────────────────────────────────
function usarTemplateBib(id){
  const b=LIBS.biblioteca.find(x=>x.id===id); if(!b) return;
  const s=getActive();
  if(!s){ alert('Selecione ou crie um aluno primeiro.'); return; }
  if(!confirm(`Aplicar o template "${b.nome}" como prescricao de ${s.perfil?.nome||'este aluno'}?\n\nO template sera carregado na ficha aprovada do aluno.`)) return;
  // Aplica como um novo treino aprovado na lista (js/treinos-store.js)
  const data = new Date().toLocaleDateString('pt-BR');

  // Aplicar um template tambem conta como "aprovacao" pra efeitos de progressao
  // futura (vault §10.2/§10.2-bis) — senao o proximo ciclo construido pelo wizard
  // normal ignoraria que isto foi prescrito, e sugeriria a partir de um historico
  // desatualizado. Fase e gravada como 'baixa' por padrao (conservador — nao temos
  // como saber em qual das 3 faixas o template se encaixa; "sempre reduzir do teto").
  if(b._fichaObj && Array.isArray(b._fichaObj.treinos) && b.objetivo){
    const exerciciosDoTemplate = b._fichaObj.treinos.flatMap(t => t.exercicios||[]);
    const objetivoAnteriorReal = s.ultimaFaseVolSessao?.objetivo || null;
    registrarHistoricoSeries(s, b.objetivo, exerciciosDoTemplate, objetivoAnteriorReal);
  }

  const novoId = criarRascunho(s);
  const treinoAplicado = aprovarRascunho(s, novoId, {
    objetivo: b.objetivo||'', nivel: b.nivel||'', frequencia: b.freq||'',
    modelo: b.modelo||'', obs: `Template: ${b.nome}`,
    treino: b.ficha_texto||b.estrutura||'', _fichaObj: b._fichaObj||null,
    _fromBiblioteca: true, _bibId: b.id,
  });

  if(b.objetivo){
    s.ultimaFaseVolSessao = { objetivo: b.objetivo, fase: 'baixa' };
  }

  saveStudent();
  // Navigate to student view
  navGo('student-view');
  selectStudent(s.id);
  if(typeof treinosAbrirAprovado==='function') treinosAbrirAprovado(novoId);
  alert(`Template "${b.nome}" aplicado com sucesso para ${s.perfil?.nome||'o aluno'}.`);
}

// ══════════════════════════════════════════════════════════════════════════
// SALVAR TREINO NA BIBLIOTECA (a partir de prescricao aprovada)
// ══════════════════════════════════════════════════════════════════════════

function abrirSalvarBiblioteca(){
  const s = getActive();
  const p = (typeof _treinoEditId!=='undefined' && _treinoEditId!=null && s) ? getTreinoPorId(s,_treinoEditId) : (s ? getUltimoTreinoAprovado(s) : null);
  if(!p || p.status!==TREINOS_STATUS.APROVADO){ alert('Nenhuma prescricao aprovada para este aluno.'); return; }

  const pf = s.perfil||{};
  const a  = s.anamnese||{};

  // Auto-fill nome
  const objLabel = {Hip:'Hipertrofia',Forca:'Forca',Emagr:'Emagrecimento',Comp:'Composicao',
    Resist:'Resistencia',CardioR:'Cardio',Func:'Funcional',Saude:'Saude',
    Esport:'Esportivo',Reab:'Reabilitacao',Envelhec:'Envelhecimento',Gestacao:'Gestacao'}[p.objetivo]||p.objetivo||'';
  const nomeSugerido = `${objLabel} ${p.frequencia||''} ${a.nivel||''} ${pf.sexo==='M'?'M':pf.sexo==='F'?'F':''}`.trim();

  const sv=(id,val)=>{
    const el=$(id); if(!el) return;
    if(el.tagName==='SELECT'){ [...el.options].some(o=>{ if(o.value===val||o.text===val){el.value=o.value;return true;} return false; }); }
    else el.value=val||'';
  };
  const tv=(id,val)=>{ const el=$(id); if(el) el.value=val||''; };

  sv('bsv-nome',      nomeSugerido);
  sv('bsv-obj',       p.objetivo||'Hip');
  sv('bsv-nivel',     a.nivel||'Iniciante');
  sv('bsv-freq',      p.frequencia||'3x');
  sv('bsv-sexo',      pf.sexo||'');
  sv('bsv-modelo',    p.modelo||'LP');

  // Populate local select from LIBS
  const localSel=$('bsv-local');
  if(localSel){
    localSel.innerHTML='<option value="">Qualquer local</option>'
      + LIBS.locais.map(l=>`<option value="${l.id}">${escHTML(l.nome)}</option>`).join('');
  }

  tv('bsv-uso',       '');
  tv('bsv-contra',    '');
  tv('bsv-crit',      '');
  tv('bsv-estrutura', '');
  tv('bsv-obs',       '');

  // Origem info
  const info=$('bsv-origem-info');
  if(info) info.textContent=`Origem: ${pf.nome||'—'} · Aprovado em: ${p.dataAprovacao||'—'} · Objetivo: ${objLabel} · Nivel: ${a.nivel||'—'}`;

  $('modal-salvar-bib').classList.remove('hidden');
}

function confirmarSalvarBiblioteca(){
  const s = getActive();
  const p = (typeof _treinoEditId!=='undefined' && _treinoEditId!=null && s) ? getTreinoPorId(s,_treinoEditId) : (s ? getUltimoTreinoAprovado(s) : null);
  if(!p || p.status!==TREINOS_STATUS.APROVADO){ alert('Nenhuma prescricao aprovada.'); return; }

  const gv=id=>$(id)?.value?.trim()||'';

  // Build sessoes from _fichaObj if available
  const sessoes = [];
  if(p._fichaObj){
    const fo = p._fichaObj;
    // fichaObj structure: {treinos: [{label, exercicios:[{nome,series,reps,...}]}]}
    (fo.treinos||[]).forEach(t=>{
      sessoes.push({
        label: t.label||t.nome||'Treino',
        exercicios: (t.exercicios||t.exs||[]).map(e=>({
          nome: e.nome||e.n||'',
          series: e.series||e.s||'',
          reps: e.reps||e.r||'',
          carga: e.carga||'',
          intervalo: e.intervalo||e.int||'',
          metodo: e.metodo||'',
        })),
      });
    });
  }

  const novo = {
    id: novoId(),
    nome:     gv('bsv-nome')||'Template sem nome',
    objetivo: gv('bsv-obj'),
    nivel:    gv('bsv-nivel'),
    freq:     gv('bsv-freq'),
    sexo:     gv('bsv-sexo'),
    modelo:   gv('bsv-modelo'),
    local_id: gv('bsv-local'),
    uso:      gv('bsv-uso'),
    contra:   gv('bsv-contra'),
    crit_ex:  gv('bsv-crit'),
    estrutura:gv('bsv-estrutura'),
    obs:      gv('bsv-obs'),
    sessoes,
    ficha_texto:   p.treino||'',
    _fichaObj:     p._fichaObj||null,
    origem_aluno:  s.perfil?.nome||'',
    origem_id:     s.id,
    origem_data:   p.dataAprovacao||new Date().toLocaleDateString('pt-BR'),
    criado_em:     new Date().toLocaleDateString('pt-BR'),
  };

  LIBS.biblioteca.push(novo);
  saveLibs(LIBS);
  $('modal-salvar-bib').classList.add('hidden');

  // Feedback
  const ind=$('saved-indicator');
  if(ind){ ind.classList.remove('hidden'); setTimeout(()=>ind.classList.add('hidden'),2000); }
  if(confirm(`Treino "${novo.nome}" salvo na Biblioteca! Deseja ir para a Biblioteca agora?`)){
    navGo('biblioteca');
  }
}

function abrirModalBib(){ preencherModalBib(null); $('modal-bib').classList.remove('hidden'); }
function fecharModalBib(){ $('modal-bib').classList.add('hidden'); }

function preencherModalBib(b){
  $('bib-edit-id').value=b?b.id:'';
  $('modal-bib-title').textContent=b?'Editar Template':'Novo Template de Treino';
  $('bib-nome').value=b?.nome||''; $('bib-obj').value=b?.objetivo||'Hipertrofia';
  $('bib-nivel').value=b?.nivel||'Iniciante'; $('bib-freq').value=b?.freq||'3x';
  $('bib-uso').value=b?.uso||''; $('bib-contra').value=b?.contra||'';
  $('bib-crit-ex').value=b?.crit_ex||''; $('bib-estrutura').value=b?.estrutura||'';
  $('bib-obs').value=b?.obs||'';
}

function editarBib(id){
  const b=LIBS.biblioteca.find(x=>x.id===id); if(!b) return;
  preencherModalBib(b); $('modal-bib').classList.remove('hidden');
}

function coletarBibDoForm(){
  const id_val=$('bib-edit-id').value;
  return {
    id:id_val?parseInt(id_val):novoId(),
    nome:$('bib-nome').value.trim()||'Sem nome',
    objetivo:$('bib-obj').value, nivel:$('bib-nivel').value, freq:$('bib-freq').value,
    uso:$('bib-uso').value.trim(), contra:$('bib-contra').value.trim(),
    crit_ex:$('bib-crit-ex').value.trim(), estrutura:$('bib-estrutura').value.trim(),
    obs:$('bib-obs').value.trim(),
  };
}
function gravarBib(novo){
  const idx=LIBS.biblioteca.findIndex(x=>x.id===novo.id);
  if(idx>=0) LIBS.biblioteca[idx]=novo; else LIBS.biblioteca.push(novo);
  saveLibs(LIBS);
}
function salvarBib(){
  gravarBib(coletarBibDoForm());
  fecharModalBib(); renderBiblioteca();
}
// Autosave — mesmo padrao do modal Local.
attachAutosave('modal-bib', coletarBibDoForm, (novo) => { $('bib-edit-id').value = novo.id; gravarBib(novo); });

