function renderDistrib(){
  const grid=$('distrib-grid'); if(!grid) return;
  grid.innerHTML='';
  if(!LIBS.distribuicao.length){
    grid.innerHTML='<div class="empty" style="grid-column:1/-1"><i class=ph-chart-bar-horizontal></i><div class="empty-title">Nenhuma divisão cadastrada</div></div>'; return;
  }

  LIBS.distribuicao.forEach(d=>{
    const card=document.createElement('div');
    card.className='card'; card.style.margin=0;

    // Dias com grupos musculares
    const diasHtml=(d.dias||[]).map((dia,i)=>{
      const isArr=Array.isArray(dia.grupos);
      const grupos=isArr?dia.grupos:[];
      const gbadges=grupos.map(g=>`<span class="badge badge-gray" style="font-size:12px">${escHTML(g)}</span>`).join('');
      const enfaseColor={MMII:'var(--blue)',MMSS:'var(--amber)',Push:'var(--red)','Pull':'var(--accent)',Full:'var(--accent-dim2)',Metabolico:'var(--amber)','Full Body':'var(--accent-dim2)'}[dia.enfase]||'var(--text3)';
      return `<div style="margin-bottom:6px">
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:3px">
          <span style="font-size:12px;font-weight:700;color:var(--text);font-variant-numeric:tabular-nums;">${escHTML(dia.label||'Treino '+String.fromCharCode(65+i))}</span>
          ${dia.enfase?`<span style="font-size:12px;font-weight:600;color:${enfaseColor};background:var(--bg4);padding:1px 6px;border-radius:10px">${escHTML(dia.enfase)}</span>`:''}
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:3px">${gbadges||'<span style="font-size:12px;color:var(--text3)">—</span>'}</div>
      </div>`;
    }).join('');

    // Objetivos e frequencias
    const objBadges=(d.objetivos_compativeis||[]).map(o=>`<span class="badge badge-green" style="font-size:12px">${escHTML(o)}</span>`).join('');
    const freqBadges=(d.freq_compativeis||[]).map(f=>`<span class="badge badge-blue" style="font-size:12px">${escHTML(f)}</span>`).join('');
    const bloqObj=(d.bloq_obj||[]).map(o=>`<span class="badge badge-red" style="font-size:12px"><i class=ph-lock></i>${escHTML(o)}</span>`).join('');
    const bloqNiv=(d.bloq_nivel||[]).map(n=>`<span class="badge badge-red" style="font-size:12px"><i class=ph-lock></i>${escHTML(n)}</span>`).join('');

    // Criterios de escolha / descarte
    const usoHtml=(d.uso_itens||d.uso?.split('|')||[]).filter(Boolean).slice(0,4)
      .map(u=>`<div style="font-size:12px;color:var(--text2)"><i class=ph-check-circle></i> ${escHTML(u.trim())}</div>`).join('');
    const contraHtml=(d.contra_itens||d.contra?.split('|')||[]).filter(Boolean).slice(0,4)
      .map(c=>`<div style="font-size:12px;color:var(--red)"><i class=ph-x-circle></i> ${escHTML(c.trim())}</div>`).join('');

    card.innerHTML=`
      <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:10px">
        <div>
          <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
            <span style="font-size:14px;font-weight:700;color:var(--text)">${escHTML(d.nome)}</span>
            <span class="badge badge-blue">${escHTML(d.freq)}</span>
            ${d.tipo_divisao?`<span class="badge badge-gray" style="font-size:12px">${escHTML(d.tipo_divisao)}</span>`:''}
            ${d.freq_musculo?`<span class="badge badge-gray" style="font-size:12px"><i class=ph-chart-bar></i> ${escHTML(d.freq_musculo)}</span>`:''}
          </div>
          ${(bloqNiv||bloqObj)?`<div style="margin-top:4px;display:flex;gap:3px;flex-wrap:wrap">${bloqNiv}${bloqObj}</div>`:''}
        </div>
        <div style="display:flex;gap:5px;flex-shrink:0">
          <button class="btn btn-ghost btn-sm" onclick="editarDistrib(${d.id})"><i class=ph-pencil-simple></i></button>
          <button class="btn btn-ghost btn-sm" style="color:var(--red)" onclick="deletarItem('distribuicao',${d.id})"><i class=ph-x></i></button>
        </div>
      </div>

      <div style="margin-bottom:10px">
        <div style="font-size:12px;font-weight:600;color:var(--text3);margin-bottom:6px">${(d.dias||[]).length} sessao(oes)/semana</div>
        ${diasHtml}
      </div>

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px">
        <div style="background:var(--accent-dim);border-radius:var(--radius);padding:8px">
          <div style="font-size:12px;font-weight:600;color:var(--accent);margin-bottom:4px"><i class=ph-check-circle></i> Usar quando</div>
          ${usoHtml||`<div style="font-size:12px;color:var(--text2)">${escHTML(d.uso||'—')}</div>`}
        </div>
        <div style="background:var(--red-dim);border-radius:var(--radius);padding:8px">
          <div style="font-size:12px;font-weight:600;color:var(--red);margin-bottom:4px"><i class=ph-x-circle></i> Descartar se</div>
          ${contraHtml||`<div style="font-size:12px;color:var(--text2)">${escHTML(d.contra||'—')}</div>`}
        </div>
      </div>

      <div style="display:flex;gap:3px;flex-wrap:wrap;margin-bottom:6px">${objBadges} ${freqBadges}</div>
      ${d.vant?`<div style="font-size:12px;color:var(--text2);margin-bottom:3px"><span style="color:var(--accent);display:inline-flex"><i class=ph-arrow-up></i></span> ${escHTML(d.vant)}</div>`:''}
      ${d.desv?`<div style="font-size:12px;color:var(--text2);margin-bottom:3px"><span style="color:var(--amber);display:inline-flex"><i class=ph-arrow-down></i></span> ${escHTML(d.desv)}</div>`:''}
      ${d.ref?`<div style="font-size:12px;color:var(--text3);margin-top:4px"><i class=ph-book-open></i> ${escHTML(d.ref)}</div>`:''}
    `;
    grid.appendChild(card);
  });
}

// ── GRUPOS CANONICOS DO VAULT ──────────────────────────────────────────────
const GRUPOS_MUSCULARES = ["Quadriceps", "Isquiossurais", "Gluteos", "Gluteos (Maximo)", "Gluteos (Medio)", "Adutores", "Iliopsoas", "Panturrilhas", "Flexores do Pe", "Peitoral", "Peitoral (Superior)", "Peitoral (Medio)", "Peitoral (Inferior)", "Latissimo", "Trapezio", "Romboides", "Deltoide", "Deltoide (Anterior)", "Deltoide (Medial)", "Deltoide (Posterior)", "Biceps", "Triceps", "Antebracos", "Reto Abdominal", "Obliquo", "Transverso do Abdomen", "Quadrado Lombar"];

function abrirModalDistrib(){ preencherModalDistrib(null); $('modal-distrib').classList.remove('hidden'); }
function fecharModalDistrib(){
  $('modal-distrib').classList.add('hidden');
  // Cancelar o formulario sem salvar nao deve executar uma navegacao que
  // estava esperando o salvamento (ver modalDivisaoSalvar/confirmarSairEdicaoDivisao)
  // — o personal continua na tela de Distribuicao com o ajuste ainda pendente.
  if(typeof _pendingNavAposDescarte!=='undefined') _pendingNavAposDescarte = null;
}

function preencherModalDistrib(d){
  $('distrib-edit-id').value=d?d.id:'';
  $('modal-distrib-title').textContent=d?'Editar Divisao':'Nova Divisao de Treino';

  const sv=(id,val)=>{ const el=$(id); if(!el) return;
    if(el.tagName==='SELECT'){ [...el.options].some(o=>{ if(o.value===val||o.text===val){el.value=o.value;return true;} return false; }); }
    else el.value=val||''; };

  sv('distrib-nome',       d?.nome||'');
  sv('distrib-tipo',       d?.tipo_divisao||'Full Body');
  sv('distrib-freq',       d?.freq||'3x');
  sv('distrib-freq-musculo', d?.freq_musculo||'2x');
  const el=$('distrib-ref'); if(el) el.value=d?.ref||'';
  sv('distrib-nivel-min',  d?.nivel_min||'');
  sv('distrib-nivel-max',  d?.nivel_max||'');
  const el2=$('distrib-vant'); if(el2) el2.value=d?.vant||'';
  const el3=$('distrib-desv'); if(el3) el3.value=d?.desv||'';

  // Frequencias compativeis
  document.querySelectorAll('.dfreq-cb').forEach(cb=>{ cb.checked=(d?.freq_compativeis||[]).includes(cb.value); });

  // Objetivos compativeis
  document.querySelectorAll('.dobj-cb').forEach(cb=>{ cb.checked=(d?.objetivos_compativeis||[]).includes(cb.value); });

  // Bloqueios nivel
  const bnMap={inic:'Iniciante',inte:'Intermediario',avan:'Avancado'};
  Object.keys(bnMap).forEach(k=>{ const el=$('dbl-'+k); if(el) el.checked=(d?.bloq_nivel||[]).includes(bnMap[k]); });

  // Bloqueios condicao
  const bcMap={gestacao:'Gestacao',lesao:'Lesao ativa',card:'Cardiopatia'};
  Object.keys(bcMap).forEach(k=>{ const el=$('dbc-'+k); if(el) el.checked=(d?.bloq_cond||[]).includes(bcMap[k]); });

  // Bloqueios objetivo
  document.querySelectorAll('.dbloq-obj-cb').forEach(cb=>{ cb.checked=(d?.bloq_obj||[]).includes(cb.value); });

  // Dias
  const diasWrap=$('distrib-dias-wrap'); if(diasWrap) diasWrap.innerHTML='';
  (d?.dias||[]).forEach(dia=>addDiaDistrib(dia));

  // Criterios de uso/contra
  const usoWrap=$('distrib-uso-wrap'); if(usoWrap) usoWrap.innerHTML='';
  const contraWrap=$('distrib-contra-wrap'); if(contraWrap) contraWrap.innerHTML='';
  (d?.uso_itens||[]).forEach(item=>addItemDistrib('uso',item));
  (d?.contra_itens||[]).forEach(item=>addItemDistrib('contra',item));
}

// ── DIAS DINAMICOS ──────────────────────────────────────────────────────────

const ENFASE_OPTS = ['MMII','MMSS','Push','Pull','Full Body','Core','Metabolico','Funcional'];

function addDiaDistrib(dia){
  const wrap=$('distrib-dias-wrap'); if(!wrap) return;
  const idx=wrap.children.length;
  const div=document.createElement('div');
  div.className='param-block'; div.style='margin-bottom:10px';
  div.dataset.diaIdx=idx;

  // Build grupos checkboxes
  const checked=(dia?.grupos)||[];
  const gruposHtml=GRUPOS_MUSCULARES.map(g=>
    `<label style="display:flex;align-items:center;gap:4px;font-size:12px;cursor:pointer;white-space:nowrap">
      <input type="checkbox" class="dia-grupo-cb" value="${g}" ${checked.includes(g)?'checked':''}> ${g}
    </label>`
  ).join('');

  const enfaseOptions=ENFASE_OPTS.map(e=>`<option ${e===(dia?.enfase)?'selected':''}>${e}</option>`).join('');

  div.innerHTML=`
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;flex-wrap:wrap">
      <div style="font-size:12px;font-weight:700;color:var(--text);font-variant-numeric:tabular-nums;">Dia ${idx+1}</div>
      <input placeholder="Label (ex: Treino A — Upper)" value="${escHTML(dia?.label||'Treino '+String.fromCharCode(65+idx))}" class="dia-label"
        style="flex:1;min-width:160px;font-size:12px;font-weight:600;padding:4px 8px;border:1px solid var(--border2);border-radius:var(--radius);background:var(--bg2);color:var(--text)">
      <select class="dia-enfase" style="font-size:12px;padding:4px 8px;border:1px solid var(--border2);border-radius:var(--radius);background:var(--bg2);color:var(--text)">
        ${enfaseOptions}
      </select>
      <button class="btn btn-ghost btn-sm" style="color:var(--red)" onclick="this.closest('[data-dia-idx]').remove()"><i class=ph-x></i></button>
    </div>
    <div style="font-size:12px;font-weight:600;color:var(--text3);margin-bottom:5px">Grupos musculares desta sessao:</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:3px 12px;background:var(--bg4);border:1px solid var(--border);border-radius:var(--radius);padding:8px 10px;max-height:160px;overflow-y:auto">
      ${gruposHtml}
    </div>`;
  wrap.appendChild(div);
}

// ── CRITERIOS DINAMICOS ────────────────────────────────────────────────────
function addItemDistrib(tipo, valor){
  const wrapId=`distrib-${tipo}-wrap`;
  const wrap=$(wrapId); if(!wrap) return;
  const div=document.createElement('div');
  div.style='display:flex;gap:6px;align-items:center;margin-bottom:4px';
  div.innerHTML=`
    <input value="${escHTML(valor||'')}" placeholder="${tipo==='uso'?'Ex: Nivel Iniciante ou Intermediario':'Ex: Nivel Avancado'}"
      class="item-criterio-${tipo}"
      style="flex:1;font-size:12px;padding:5px 8px;border:1px solid var(--border2);border-radius:var(--radius);background:var(--bg2);color:var(--text)">
    <button class="btn btn-ghost btn-sm" style="color:var(--red);flex-shrink:0" onclick="this.parentElement.remove()"><i class=ph-x></i></button>`;
  wrap.appendChild(div);
}

function editarDistrib(id){
  const d=LIBS.distribuicao.find(x=>x.id===id); if(!d) return;
  preencherModalDistrib(d); $('modal-distrib').classList.remove('hidden');
}

function salvarDistrib(){
  const id_val=$('distrib-edit-id').value;

  // Frequencias compativeis
  const freqs=[...document.querySelectorAll('.dfreq-cb:checked')].map(cb=>cb.value);

  // Objetivos compativeis
  const objs=[...document.querySelectorAll('.dobj-cb:checked')].map(cb=>cb.value);

  // Bloqueios nivel
  const bnMap={inic:'Iniciante',inte:'Intermediario',avan:'Avancado'};
  const bloqNiv=Object.keys(bnMap).filter(k=>{ const el=$('dbl-'+k);return el&&el.checked; }).map(k=>bnMap[k]);

  // Bloqueios condicao
  const bcMap={gestacao:'Gestacao',lesao:'Lesao ativa',card:'Cardiopatia'};
  const bloqCond=Object.keys(bcMap).filter(k=>{ const el=$('dbc-'+k);return el&&el.checked; }).map(k=>bcMap[k]);

  // Bloqueios objetivo
  const bloqObj=[...document.querySelectorAll('.dbloq-obj-cb:checked')].map(cb=>cb.value);

  // Dias — coleta label, enfase, grupos
  const diasWrap=$('distrib-dias-wrap');
  const dias=[...diasWrap.querySelectorAll('[data-dia-idx]')].map((div,i)=>{
    const label=div.querySelector('.dia-label')?.value||'Treino '+String.fromCharCode(65+i);
    const enfase=div.querySelector('.dia-enfase')?.value||'';
    const grupos=[...div.querySelectorAll('.dia-grupo-cb:checked')].map(cb=>cb.value);
    return {label, enfase, grupos};
  });

  // Criterios uso / contra
  const uso_itens=[...document.querySelectorAll('.item-criterio-uso')].map(el=>el.value.trim()).filter(Boolean);
  const contra_itens=[...document.querySelectorAll('.item-criterio-contra')].map(el=>el.value.trim()).filter(Boolean);

  const gv=id=>$(id)?.value?.trim()||'';
  const novo={
    id:id_val?parseInt(id_val):novoId(),
    nome:gv('distrib-nome')||'Sem nome',
    tipo_divisao:gv('distrib-tipo'),
    freq:gv('distrib-freq'),
    freq_musculo:gv('distrib-freq-musculo'),
    ref:gv('distrib-ref'),
    nivel_min:gv('distrib-nivel-min'),
    nivel_max:gv('distrib-nivel-max'),
    objetivos_compativeis:objs,
    freq_compativeis:freqs,
    bloq_nivel:bloqNiv,
    bloq_cond:bloqCond,
    bloq_obj:bloqObj,
    dias,
    uso_itens,
    contra_itens,
    uso:uso_itens.join(' | '),
    contra:contra_itens.join(' | '),
    vant:gv('distrib-vant'),
    desv:gv('distrib-desv'),
  };
  if(id_val){ const idx=LIBS.distribuicao.findIndex(x=>x.id===novo.id); if(idx>=0) LIBS.distribuicao[idx]=novo; else LIBS.distribuicao.push(novo); }
  else LIBS.distribuicao.push(novo);
  saveLibs(LIBS); fecharModalDistrib(); renderDistrib();
}

