let _delPending=null;
function deletarItem(colecao, id){
  // Local-base interno (id=-1) nao pode ser excluido
  if(colecao==='locais' && id===-1){ alert('Este local e interno e nao pode ser excluido.'); return; }
  const nomes={'locais':'local','biblioteca':'template','distribuicao':'divisao','periodizacao':'modelo'};
  const alvo = (LIBS[colecao]||[]).find(x=>x.id===id);
  $('modal-del-msg').textContent =
    `Excluir ${nomes[colecao]||'item'} "${alvo?.nome||'—'}"? ` +
    `Ele vai para Arquivadas, onde voce pode consultar ou restaurar quando quiser. Nada e apagado de verdade.`;
  _delPending={colecao,id};
  $('modal-del-confirm').onclick=confirmarDeletar;
  $('modal-del-lib').classList.remove('hidden');
}
function confirmarDeletar(){
  if(!_delPending) return;
  const {colecao,id}=_delPending;
  // Um unico ponto cobre local, template, divisao e periodizacao — as quatro
  // colecoes de LIBS ja passavam por aqui.
  const alvo = (LIBS[colecao]||[]).find(x=>x.id===id);
  if(alvo) arquivarItem(ARQ_TIPO_POR_COLECAO[colecao] || colecao, alvo, {});
  LIBS[colecao]=LIBS[colecao].filter(x=>x.id!==id);
  saveLibs(LIBS);
  if(typeof supaSalvarAgora === 'function') supaSalvarAgora();
  closeDelModal();
  if(colecao==='locais')       renderLocais();
  if(colecao==='biblioteca')   renderBiblioteca();
  if(colecao==='distribuicao'){
    renderDistrib();
    // Se esse mesmo modelo tambem estava listado na tela de Distribuicao (Step 2)
    // de uma prescricao em andamento, tira o card de la tambem — senao ele some
    // da biblioteca mas fica "fantasma" na tela onde o personal estava escolhendo.
    if(typeof _s3!=='undefined' && _s3?.divisaoOpcoes){
      const idx = _s3.divisaoOpcoes.findIndex(op => op._libId === id);
      if(idx >= 0 && typeof removerDivisaoOpcaoDaLista==='function') removerDivisaoOpcaoDaLista(idx);
    }
  }
  if(colecao==='periodizacao') renderPeriod();
}
function closeDelModal(){ $('modal-del-lib').classList.add('hidden'); _delPending=null; }

// Fechar modais clicando fora
['modal-local','modal-bib','modal-distrib','modal-del-lib'].forEach(id=>{
  const el=$(id);
  if(el) el.addEventListener('click',function(e){ if(e.target===this){ this.classList.add('hidden'); _delPending=null; } });
});

// Ícone + rótulo do botão de tema (o ícone é uma <i> do Phosphor, troca-se a classe).
function _aplicarRotuloTema(isDark){
  const icon  = $('tema-icon');
  const label = $('tema-label');
  if(icon)  icon.className  = isDark ? 'ph-sun' : 'ph-moon';
  if(label) label.textContent = isDark ? 'Modo claro' : 'Modo escuro';
}
function toggleTema(){
  const isDark = document.documentElement.classList.toggle('dark');
  _aplicarRotuloTema(isDark);
  try { localStorage.setItem('acm-tema', isDark ? 'dark' : 'light'); } catch(e){}
}
(function(){
  try {
    const saved = localStorage.getItem('acm-tema');
    if(saved === 'dark'){
      document.documentElement.classList.add('dark');
      setTimeout(()=>_aplicarRotuloTema(true), 100);
    }
  } catch(e){}
})();

