// Mapa padrao de movimento → aquecimento sugerido (Vault FASE-3 §2)
const AQUECIMENTO_PADRAO = {
  'Quadriceps':    'Agachamento ar ×15 + passada caminhando ×10/lado + leg press leve (50%) ×15',
  'Gluteos':       'Elevacao quadril bodyweight ×20 + abducao quadril elastico ×15/lado',
  'Isquiossurais': 'Stiff leve (sem carga) ×15 + leg curl leve (40%) ×15 + RDL elastico ×12',
  'Peitoral':      'Flexao de braco ×10 + voador leve ×15 + rotacao escapular ×10/lado',
  'Latissimo':     'Band pull-apart ×15 + remada elastico ×15 + retracao escapular ×10',
  'Deltoide':      'Circulo de ombros ×10 + elevacao lateral leve ×15 + face pull elastico ×15',
  'Trapezio':      'Encolhimento sem peso ×20 + retracao escap. ×10 + neck roll ×5/lado',
  'Biceps':        'Rosca martelo elastico ×15 + supinacao ×10/lado + circunducao punho ×10',
  'Triceps':       'Extensao triceps elastico ×15 + flexao de cotovelo reversa ×10',
  'Reto Abdominal':'Prancha 20s + crunch abdominal ×15 + hollow body 10s',
  'Panturrilhas':  'Elevacao unilateral sem peso ×20/lado + rotacao tornozelo ×10/lado',
};

// Usada so pelo PDF, pra virar uma linha de texto. Prioriza o aquecimento
// especifico por articulacao (treino.aquecimento — ver gerarAquecimentoArticular
// em prescricao-motor.js, gerado junto com a ficha a partir dos exercicios
// principais de fato escolhidos), com fallback pro mapa generico por grupo
// muscular (AQUECIMENTO_PADRAO) so pra fichas salvas antes desse recurso existir.
function gerarAquecimentoSessao(treino){
  if(treino.aquecimento && treino.aquecimento.length){
    return treino.aquecimento.map(a => `${a.nome} (${a.duracao})`).join(' | ');
  }
  const grupos = [...new Set(treino.exercicios.map(e=>e.musculo))];
  const itens = grupos
    .map(g => AQUECIMENTO_PADRAO[g])
    .filter(Boolean)
    .filter((v,i,a)=>a.indexOf(v)===i); // unique
  if(!itens.length) return '5 min esteira leve + mobilidade articular geral';
  return itens.join(' | ');
}

