// Hook: apos salvar divisao, atualizar step2 se callback pendente
// (movido pra ca porque salvarDistrib so existe depois que este arquivo carrega —
// no arquivo original monolitico isso nao importava, hoisting resolvia sozinho)
const _origSalvarDistrib = salvarDistrib;
salvarDistrib = function(){
  // Precisa capturar ANTES de chamar o original: salvarDistrib() de verdade
  // fecha o modal chamando fecharModalDistrib(), que zera _pendingNavAposDescarte
  // (esse zerar e o comportamento certo pra quando o personal CANCELA o modal
  // sem salvar — ver fecharModalDistrib). Aqui e um salvamento de verdade, entao
  // guardamos a navegacao pendente antes desse efeito colateral apagar ela.
  const navPendente = (typeof _pendingNavAposDescarte!=='undefined') ? _pendingNavAposDescarte : null;
  const tinhaCallbackPendente = _pendingDivisaoCallback;
  _origSalvarDistrib();
  if(tinhaCallbackPendente){
    _pendingDivisaoCallback = false;
    const freq = val('pr-frequencia') || '3x';
    const numDias = parseInt(freq)||3;
    // A lista e regenerada do zero aqui — isso tambem e o que limpa qualquer
    // card com ajuste nao salvo (_chaveOriginal) da lista antiga: o modelo
    // recem-salvo ja esta na biblioteca de verdade, entao o aviso de "ajuste
    // nao salvo" deixa de fazer sentido (ver temEdicaoDivisaoNaoSalva).
    _s3.divisaoOpcoes = gerarDivisoesBalanceadas(numDias, selectedObj || 'Saude');
    _s3._divChaveGeracao = numDias + '|' + (selectedObj || 'Saude');
    _s3._dcEditando = undefined;
    renderTelaDivisao();
    // Retoma a navegacao que o personal tinha pedido antes de "Salvar como
    // modelo" (ex: trocar de aba, voltar pra lista) — so depois do salvamento
    // realmente acontecer, nunca antes.
    if(navPendente){
      if(typeof _pendingNavAposDescarte!=='undefined') _pendingNavAposDescarte = null;
      navPendente();
    }
  }
};
